export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout: string;
  [key: string]: unknown;
}

export interface Page {
  /** Path of the source file relative to the source dir, e.g. "posts/hello.md" */
  sourcePath: string;
  /** Output path relative to the output dir, e.g. "posts/hello.html" */
  outputPath: string;
  /** Site-absolute URL, e.g. "/posts/hello.html" */
  url: string;
  frontmatter: Frontmatter;
  /** Raw markdown body (without frontmatter) */
  body: string;
  /** Rendered HTML body */
  html: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  siteTitle: string;
  siteUrl: string;
  siteDescription: string;
  includeDrafts: boolean;
}

export interface SiteContext {
  title: string;
  url: string;
  description: string;
  pages: Page[];
  tags: Record<string, Page[]>;
}

import matter from "gray-matter";
import type { Frontmatter } from "./types.js";

export interface ParsedDocument {
  frontmatter: Frontmatter;
  body: string;
}

function toDate(value: unknown): Date | null {
  if (value instanceof Date) return isNaN(value.getTime()) ? null : value;
  if (typeof value === "string" || typeof value === "number") {
    const d = new Date(value);
    return isNaN(d.getTime()) ? null : d;
  }
  return null;
}

function toTags(value: unknown): string[] {
  if (Array.isArray(value)) return value.map(String).map((t) => t.trim()).filter(Boolean);
  if (typeof value === "string") {
    return value.split(",").map((t) => t.trim()).filter(Boolean);
  }
  return [];
}

/**
 * Parse a Markdown document with optional YAML frontmatter.
 * Normalizes the well-known keys: title, date, tags, draft, layout.
 * Unknown keys are preserved verbatim.
 */
export function parseDocument(raw: string, fallbackTitle = "Untitled"): ParsedDocument {
  const { data, content } = matter(raw);
  const frontmatter: Frontmatter = {
    ...data,
    title: typeof data.title === "string" && data.title.trim() ? data.title.trim() : fallbackTitle,
    date: toDate(data.date),
    tags: toTags(data.tags),
    draft: data.draft === true,
    layout: typeof data.layout === "string" && data.layout.trim() ? data.layout.trim() : "default",
  };
  return { frontmatter, body: content };
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

/**
 * A single shared Marked instance with syntax highlighting.
 * Reused across all pages for throughput: highlight.js language
 * grammars are compiled once and cached.
 */
const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code, lang) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  })
);

export function renderMarkdown(body: string): string {
  return marked.parse(body, { async: false }) as string;
}

import Handlebars from "handlebars";
import { promises as fs } from "node:fs";
import path from "node:path";

export interface TemplateEngine {
  /** Render a named layout (file name without extension) with a context. */
  render(layout: string, context: Record<string, unknown>): string;
  hasLayout(layout: string): boolean;
}

const TEMPLATE_EXTENSIONS = new Set([".hbs", ".handlebars", ".html"]);

async function walk(dir: string): Promise<string[]> {
  const out: string[] = [];
  let entries;
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await walk(full)));
    else out.push(full);
  }
  return out;
}

function registerHelpers(hb: typeof Handlebars): void {
  hb.registerHelper("formatDate", (date: unknown, fmt?: unknown) => {
    if (!(date instanceof Date) || isNaN(date.getTime())) return "";
    if (typeof fmt === "string" && fmt === "iso") return date.toISOString();
    return date.toISOString().slice(0, 10);
  });
  hb.registerHelper("eq", (a: unknown, b: unknown) => a === b);
  hb.registerHelper("json", (v: unknown) => JSON.stringify(v));
}

/**
 * Create a template engine from a template directory.
 *
 * Layout resolution:
 *   - `layouts/<name>.hbs` (or .handlebars/.html), falling back to `<name>.hbs`
 *     at the template root.
 * Partials:
 *   - every file under `partials/` is registered as a partial named by its
 *     path relative to `partials/` without extension (e.g. partials/nav.hbs -> {{> nav}}).
 *
 * All templates are compiled once up-front (throughput-oriented): renders are
 * pure function calls with zero I/O.
 */
export async function createTemplateEngine(templateDir: string): Promise<TemplateEngine> {
  const hb = Handlebars.create();
  registerHelpers(hb);

  const layouts = new Map<string, Handlebars.TemplateDelegate>();
  const files = await walk(templateDir);

  for (const file of files) {
    const ext = path.extname(file);
    if (!TEMPLATE_EXTENSIONS.has(ext)) continue;
    const rel = path.relative(templateDir, file).split(path.sep).join("/");
    const name = rel.slice(0, -ext.length);
    const source = await fs.readFile(file, "utf8");

    if (name.startsWith("partials/")) {
      hb.registerPartial(name.slice("partials/".length), source);
    } else if (name.startsWith("layouts/")) {
      layouts.set(name.slice("layouts/".length), hb.compile(source));
    } else {
      // root-level templates also usable as layouts
      if (!layouts.has(name)) layouts.set(name, hb.compile(source));
    }
  }

  return {
    hasLayout: (layout) => layouts.has(layout),
    render(layout, context) {
      const tpl = layouts.get(layout);
      if (!tpl) {
        throw new Error(
          `Layout "${layout}" not found in ${templateDir} (looked in layouts/ and template root)`
        );
      }
      return tpl(context);
    },
  };
}

import type { Page, SiteConfig } from "./types.js";

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function absoluteUrl(base: string, url: string): string {
  return base.replace(/\/+$/, "") + url;
}

/** Generate an RSS 2.0 feed for the given pages (newest first). */
export function generateRss(config: SiteConfig, pages: Page[]): string {
  const sorted = [...pages].sort(
    (a, b) => (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0)
  );
  const items = sorted
    .map((page) => {
      const link = absoluteUrl(config.siteUrl, page.url);
      const pubDate = page.frontmatter.date ? `\n      <pubDate>${page.frontmatter.date.toUTCString()}</pubDate>` : "";
      return `    <item>
      <title>${escapeXml(page.frontmatter.title)}</title>
      <link>${escapeXml(link)}</link>
      <guid>${escapeXml(link)}</guid>${pubDate}
      <description><![CDATA[${page.html}]]></description>
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${escapeXml(config.siteUrl)}</link>
    <description>${escapeXml(config.siteDescription)}</description>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items}
  </channel>
</rss>
`;
}

import { promises as fs } from "node:fs";
import path from "node:path";
import { parseDocument } from "./frontmatter.js";
import { renderMarkdown } from "./markdown.js";
import { createTemplateEngine, type TemplateEngine } from "./templates.js";
import { generateRss } from "./rss.js";
import type { Page, SiteConfig, SiteContext } from "./types.js";

export interface BuildResult {
  pages: Page[];
  tagPages: string[];
  wroteRss: boolean;
  skippedDrafts: number;
}

async function walkMarkdown(dir: string, base = dir): Promise<string[]> {
  const out: string[] = [];
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await walkMarkdown(full, base)));
    else if (/\.(md|markdown)$/i.test(entry.name)) out.push(full);
  }
  return out;
}

function slugifyTag(tag: string): string {
  return tag
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export async function loadPages(config: SiteConfig): Promise<{ pages: Page[]; skippedDrafts: number }> {
  const files = await walkMarkdown(config.sourceDir);
  let skippedDrafts = 0;

  // Throughput: parse + render all files concurrently.
  const results = await Promise.all(
    files.map(async (file): Promise<Page | null> => {
      const raw = await fs.readFile(file, "utf8");
      const rel = path.relative(config.sourceDir, file).split(path.sep).join("/");
      const fallbackTitle = path.basename(rel).replace(/\.(md|markdown)$/i, "");
      const { frontmatter, body } = parseDocument(raw, fallbackTitle);
      if (frontmatter.draft && !config.includeDrafts) {
        skippedDrafts++;
        return null;
      }
      const outputPath = rel.replace(/\.(md|markdown)$/i, ".html");
      return {
        sourcePath: rel,
        outputPath,
        url: "/" + outputPath,
        frontmatter,
        body,
        html: renderMarkdown(body),
      };
    })
  );

  const pages = results.filter((p): p is Page => p !== null);
  // Deterministic order: newest first, ties broken by path.
  pages.sort((a, b) => {
    const diff = (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0);
    return diff !== 0 ? diff : a.sourcePath.localeCompare(b.sourcePath);
  });
  return { pages, skippedDrafts };
}

export function collectTags(pages: Page[]): Record<string, Page[]> {
  const tags: Record<string, Page[]> = {};
  for (const page of pages) {
    for (const tag of page.frontmatter.tags) {
      (tags[tag] ??= []).push(page);
    }
  }
  return tags;
}

function renderPage(engine: TemplateEngine, page: Page, site: SiteContext): string {
  const layout = engine.hasLayout(page.frontmatter.layout) ? page.frontmatter.layout : "default";
  return engine.render(layout, {
    ...page.frontmatter,
    content: page.html,
    page,
    site,
  });
}

async function writeFile(outputDir: string, relPath: string, content: string): Promise<void> {
  const full = path.join(outputDir, relPath);
  await fs.mkdir(path.dirname(full), { recursive: true });
  await fs.writeFile(full, content, "utf8");
}

/** Full site build: pages, tag index pages, RSS feed. */
export async function buildSite(config: SiteConfig): Promise<BuildResult> {
  const [engine, loaded] = await Promise.all([
    createTemplateEngine(config.templateDir),
    loadPages(config),
  ]);
  const { pages, skippedDrafts } = loaded;
  const tags = collectTags(pages);
  const site: SiteContext = {
    title: config.siteTitle,
    url: config.siteUrl,
    description: config.siteDescription,
    pages,
    tags,
  };

  await fs.mkdir(config.outputDir, { recursive: true });

  // Throughput: all writes issued concurrently.
  const writes: Promise<void>[] = pages.map((page) =>
    writeFile(config.outputDir, page.outputPath, renderPage(engine, page, site))
  );

  // Tag index pages: /tags/<slug>.html using the "tag" layout if present.
  const tagPages: string[] = [];
  for (const [tag, tagged] of Object.entries(tags)) {
    const rel = path.posix.join("tags", `${slugifyTag(tag)}.html`);
    tagPages.push(rel);
    const html = engine.hasLayout("tag")
      ? engine.render("tag", { tag, pages: tagged, site })
      : defaultTagIndex(tag, tagged);
    writes.push(writeFile(config.outputDir, rel, html));
  }

  // RSS feed at /feed.xml
  writes.push(writeFile(config.outputDir, "feed.xml", generateRss(config, pages)));

  await Promise.all(writes);
  return { pages, tagPages, wroteRss: true, skippedDrafts };
}

function defaultTagIndex(tag: string, pages: Page[]): string {
  const items = pages
    .map((p) => `<li><a href="${p.url}">${p.frontmatter.title}</a></li>`)
    .join("\n      ");
  return `<!doctype html>
<html>
<head><meta charset="utf-8"><title>Tag: ${tag}</title></head>
<body>
  <h1>Tag: ${tag}</h1>
  <ul>
      ${items}
  </ul>
</body>
</html>
`;
}

import { createServer, type Server } from "node:http";
import { promises as fs } from "node:fs";
import path from "node:path";
import chokidar, { type FSWatcher } from "chokidar";
import { WebSocketServer, WebSocket } from "ws";
import { buildSite } from "./build.js";
import type { SiteConfig } from "./types.js";

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json",
  ".xml": "application/xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
};

export const RELOAD_SCRIPT = `<script>
(() => {
  const ws = new WebSocket("ws://" + location.host + "/__livereload");
  ws.onmessage = (e) => { if (e.data === "reload") location.reload(); };
  ws.onclose = () => setTimeout(() => location.reload(), 1000);
})();
</script>`;

/** Inject the live-reload script before </body>, or append if absent. */
export function injectReloadScript(html: string): string {
  const idx = html.lastIndexOf("</body>");
  if (idx === -1) return html + RELOAD_SCRIPT;
  return html.slice(0, idx) + RELOAD_SCRIPT + html.slice(idx);
}

export interface DevServer {
  server: Server;
  close(): Promise<void>;
  port: number;
}

export async function startDevServer(config: SiteConfig, port: number): Promise<DevServer> {
  await buildSite(config);

  const server = createServer(async (req, res) => {
    try {
      const urlPath = decodeURIComponent((req.url ?? "/").split("?")[0]);
      let relPath = urlPath.endsWith("/") ? urlPath + "index.html" : urlPath;
      relPath = path.normalize(relPath).replace(/^([/\\]|\.\.)+/, "");
      const filePath = path.join(config.outputDir, relPath);
      if (!path.resolve(filePath).startsWith(path.resolve(config.outputDir))) {
        res.writeHead(403);
        res.end("Forbidden");
        return;
      }
      let data: Buffer;
      try {
        data = await fs.readFile(filePath);
      } catch {
        res.writeHead(404, { "Content-Type": "text/html; charset=utf-8" });
        res.end(injectReloadScript("<h1>404 Not Found</h1>"));
        return;
      }
      const ext = path.extname(filePath).toLowerCase();
      const mime = MIME[ext] ?? "application/octet-stream";
      if (ext === ".html") {
        res.writeHead(200, { "Content-Type": mime });
        res.end(injectReloadScript(data.toString("utf8")));
      } else {
        res.writeHead(200, { "Content-Type": mime });
        res.end(data);
      }
    } catch (err) {
      res.writeHead(500);
      res.end(String(err));
    }
  });

  const wss = new WebSocketServer({ server, path: "/__livereload" });
  const broadcast = () => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) client.send("reload");
    }
  };

  let rebuilding = false;
  let pending = false;
  const rebuild = async () => {
    if (rebuilding) {
      pending = true;
      return;
    }
    rebuilding = true;
    try {
      await buildSite(config);
      broadcast();
      console.log("[ssg] rebuilt, reload sent");
    } catch (err) {
      console.error("[ssg] rebuild failed:", err);
    } finally {
      rebuilding = false;
      if (pending) {
        pending = false;
        void rebuild();
      }
    }
  };

  const watcher: FSWatcher = chokidar.watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 50, pollInterval: 10 },
  });
  watcher.on("all", () => void rebuild());

  await new Promise<void>((resolve) => server.listen(port, resolve));
  const actualPort = (server.address() as { port: number }).port;
  console.log(`[ssg] dev server at http://localhost:${actualPort}`);

  return {
    server,
    port: actualPort,
    async close() {
      await watcher.close();
      wss.close();
      await new Promise<void>((resolve, reject) =>
        server.close((err) => (err ? reject(err) : resolve()))
      );
    },
  };
}

#!/usr/bin/env node
import path from "node:path";
import { buildSite } from "./build.js";
import { startDevServer } from "./server.js";
import type { SiteConfig } from "./types.js";

const HELP = `ssg - static site generator

Usage:
  ssg build [options]   Build the site once
  ssg serve [options]   Build, serve, and live-reload on changes

Options:
  -s, --source <dir>      Source directory of Markdown files   (default: content)
  -t, --templates <dir>   Handlebars template directory        (default: templates)
  -o, --output <dir>      Output directory                     (default: dist-site)
  -p, --port <port>       Dev server port (serve only)         (default: 3000)
      --drafts            Include pages marked draft: true
      --site-title <s>    Site title for RSS                   (default: "My Site")
      --site-url <s>      Absolute site URL for RSS            (default: "http://localhost:3000")
      --site-desc <s>     Site description for RSS
  -h, --help              Show this help
`;

export interface CliOptions {
  command: "build" | "serve" | "help";
  config: SiteConfig;
  port: number;
}

export class CliError extends Error {}

/** Parse argv (without node/script prefix) into structured options. */
export function parseArgs(argv: string[]): CliOptions {
  let command: CliOptions["command"] | null = null;
  const opts = {
    source: "content",
    templates: "templates",
    output: "dist-site",
    port: 3000,
    drafts: false,
    siteTitle: "My Site",
    siteUrl: "http://localhost:3000",
    siteDesc: "",
  };

  const takeValue = (flag: string, i: number): string => {
    const v = argv[i + 1];
    if (v === undefined || v.startsWith("-")) throw new CliError(`Missing value for ${flag}`);
    return v;
  };

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    switch (arg) {
      case "build":
      case "serve":
        if (command) throw new CliError(`Unexpected extra command "${arg}"`);
        command = arg;
        break;
      case "-s":
      case "--source":
        opts.source = takeValue(arg, i++);
        break;
      case "-t":
      case "--templates":
        opts.templates = takeValue(arg, i++);
        break;
      case "-o":
      case "--output":
        opts.output = takeValue(arg, i++);
        break;
      case "-p":
      case "--port": {
        const raw = takeValue(arg, i++);
        const port = Number(raw);
        if (!Number.isInteger(port) || port < 0 || port > 65535) {
          throw new CliError(`Invalid port: ${raw}`);
        }
        opts.port = port;
        break;
      }
      case "--drafts":
        opts.drafts = true;
        break;
      case "--site-title":
        opts.siteTitle = takeValue(arg, i++);
        break;
      case "--site-url":
        opts.siteUrl = takeValue(arg, i++);
        break;
      case "--site-desc":
        opts.siteDesc = takeValue(arg, i++);
        break;
      case "-h":
      case "--help":
        command = "help";
        break;
      default:
        throw new CliError(`Unknown argument: ${arg}`);
    }
    if (command === "help") break;
  }

  if (!command) throw new CliError('Missing command: expected "build" or "serve"');

  return {
    command,
    port: opts.port,
    config: {
      sourceDir: path.resolve(opts.source),
      templateDir: path.resolve(opts.templates),
      outputDir: path.resolve(opts.output),
      siteTitle: opts.siteTitle,
      siteUrl: opts.siteUrl,
      siteDescription: opts.siteDesc,
      includeDrafts: opts.drafts,
    },
  };
}

export async function main(argv: string[]): Promise<number> {
  let options: CliOptions;
  try {
    options = parseArgs(argv);
  } catch (err) {
    if (err instanceof CliError) {
      console.error(`Error: ${err.message}\n`);
      console.error(HELP);
      return 2;
    }
    throw err;
  }

  if (options.command === "help") {
    console.log(HELP);
    return 0;
  }

  if (options.command === "build") {
    const start = performance.now();
    const result = await buildSite(options.config);
    const ms = (performance.now() - start).toFixed(0);
    console.log(
      `Built ${result.pages.length} page(s), ${result.tagPages.length} tag page(s), feed.xml in ${ms}ms` +
        (result.skippedDrafts ? ` (skipped ${result.skippedDrafts} draft(s))` : "")
    );
    return 0;
  }

  await startDevServer(options.config, options.port);
  return 0;
}

// Only run when executed directly, not when imported by tests.
const isDirect = process.argv[1] && import.meta.url.endsWith(path.basename(process.argv[1]));
if (isDirect) {
  main(process.argv.slice(2))
    .then((code) => {
      if (code !== 0) process.exitCode = code;
    })
    .catch((err) => {
      console.error(err);
      process.exitCode = 1;
    });
}

